+" IMPORTERADDRESS, IMPORTERPHONENO, IMPORTERBANK, BICCODE, IBANACCOUNT, BANKCOUNTRY, BANKADDRESS, "
+" BANKPHONENO, COLLECTINGBANKREF , "//64
+"ODC_FCTRANSACTION.ACCOUNTNO, ODC_FCTRANSACTION.POSTINGDATE, ODC_FCTRANSACTION.VALUEDATE, ODC_FCTRANSACTION.TRANSACTIONAMOUNT, ODC_FCTRANSACTION.AMOUNTINBPM, "
+" ODC_PARTIESINFO.PARTYID, ODC_PARTIESINFO.PARTYTYPE, ODC_PARTIESINFO.CIF"
+" FROM "+tw.env.LKP_DB_Schema+".ODC_REQUESTINFO"
+" Inner join "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION on ODC_REQUESTINFO.ID = ODC_FCTRANSACTION.REQUESRID " 
+" Inner join "+tw.env.LKP_DB_Schema+".ODC_PARTIESINFO on ODC_REQUESTINFO.ID = ODC_PARTIESINFO.REQUESRID "

+" where ODC_REQUESTINFO.REQUESTNO like '"+tw.local.requestNumber+"' ; "



