		}
	}
	if(tw.local.odcRequest.BasicDetails.requestType == ""+tw.epv.RequestType.Collection){
		if (tw.local.odcRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.odcRequest.appInfo.status == tw.epv.Status.terminated+"") {
			tw.local.odcRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.BasicDetails.parentRequestNo+"ODC/Canceled Cases"+"/Collection "+tw.local.odcRequest.requestNo;
		}
		else{
			tw.local.odcRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.BasicDetails.parentRequestNo+"ODC"+"/Collection "+tw.local.odcRequest.requestNo;
		}
	}
	if(tw.local.odcRequest.BasicDetails.requestType == ""+tw.epv.RequestType.Closure){
		if (tw.local.odcRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.odcRequest.appInfo.status == tw.epv.Status.terminated+"") {
			tw.local.odcRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.BasicDetails.parentRequestNo+"ODC/Canceled Cases"+"/Closure "+tw.local.odcRequest.requestNo;
		}
		else{
			tw.local.odcRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.BasicDetails.parentRequestNo+"ODC"+"/Closure "+tw.local.odcRequest.requestNo;
		}
	}
	if(tw.local.odcRequest.BasicDetails.requestType == ""+tw.epv.RequestType.Reversal){
		if (tw.local.odcRequest.appInfo.status == tw.epv.Status.Canceled+"" || tw.local.odcRequest.appInfo.status == tw.epv.Status.terminated+"") {
			tw.local.odcRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.BasicDetails.parentRequestNo+"ODC/Canceled Cases"+"/Reversal "+tw.local.odcRequest.requestNo;
		}
		else{
			tw.local.odcRequest.attachmentDetails.ecmProperties.fullPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.BasicDetails.parentRequestNo+"ODC"+"/Reversal "+tw.local.odcRequest.requestNo;
		}
	}
}

